<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { evaluationApi } from '@/api'

const rows=ref<any[]>([]); const total=ref(0); const loading=ref(false)
const query=reactive({pageNum:1,pageSize:10,title:'',status:''})
const dialogVisible=ref(false); const editId=ref<number|null>(null)
const form=reactive({title:'',description:'',startTime:'',endTime:'',targetType:'STUDENT',targetScope:'',questions:''})

async function load(){loading.value=true;try{const params={...query};Object.keys(params).forEach(k=>{if(params[k]===''||params[k]==null)delete params[k]});const raw:any=await evaluationApi.questionnairePage(params);const body=raw?.data??raw;rows.value=body?.records??[];total.value=Number(body?.total??rows.value.length)}finally{loading.value=false}}
function openCreate(){editId.value=null;Object.assign(form,{title:'',description:'',startTime:'',endTime:'',targetType:'STUDENT',targetScope:'',questions:''});dialogVisible.value=true}
function openEdit(row:any){editId.value=row.id;Object.assign(form,{title:row.title,description:row.description,startTime:row.startTime,endTime:row.endTime,targetType:row.targetType,targetScope:(row.targetScope||[]).join(','),questions:JSON.stringify(row.questions||[])});dialogVisible.value=true}
async function submit(){try{const questions=JSON.parse(form.questions||'[]');const targetScope=String(form.targetScope||'').split(',').map((s:string)=>s.trim()).filter(Boolean).map(Number);const data={...form,targetScope,questions};if(editId.value===null)await evaluationApi.createQuestionnaire(data);else await evaluationApi.updateQuestionnaire(editId.value,data);ElMessage.success('保存成功');dialogVisible.value=false;load()}catch{ElMessage.warning('questions 需为 JSON 数组')}}
async function remove(row:any){await ElMessageBox.confirm('确定删除该问卷吗？','提示',{type:'warning'});try{await evaluationApi.deleteQuestionnaire(row.id);ElMessage.success('删除成功');load()}catch{}}
async function finish(row:any){try{await evaluationApi.finishQuestionnaire(row.id);ElMessage.success('已结束');load()}catch{}}
onMounted(load)
</script>
<template><section class="hs-page"><div class="hs-page-title"><div class="cn">问卷管理</div><div class="en">Questionnaires</div><div class="hs-waterline"></div></div><div class="hs-panel"><el-form inline @submit.prevent><el-form-item label="标题"><el-input v-model="query.title" clearable style="width:160px"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:140px"><el-option v-for="s in ['WAITING','RUNNING','FINISHED','CANCELLED']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button type="primary" @click="openCreate">创建问卷</el-button></el-form><el-table :data="rows" border stripe v-loading="loading"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="title" label="标题"/><el-table-column prop="status" label="状态"/><el-table-column prop="targetType" label="目标类型"/><el-table-column prop="totalCount" label="总人数"/><el-table-column prop="submitCount" label="已提交"/><el-table-column prop="createTime" label="创建时间"/><el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status==='RUNNING'" link type="warning" @click="finish(row)">结束</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></div><el-dialog v-model="dialogVisible" :title="editId===null?'创建问卷':'编辑问卷'" width="640px"><el-form :model="form" label-width="100px"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="form.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="目标类型"><el-select v-model="form.targetType"><el-option v-for="t in ['STUDENT','BUILDING','CAMPUS','ALL']" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item label="目标范围"><el-input v-model="form.targetScope" placeholder="逗号分隔的ID，如 1,2,3"/></el-form-item><el-form-item label="题目JSON"><el-input v-model="form.questions" type="textarea" :rows="7" placeholder='[{"title":"请打分","type":"SCORE","minScore":0,"maxScore":5,"requiredFlag":"YES","sort":0}]'/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></template></el-dialog></section></template>
<style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>